input.command:
cd /tmp/dfz && dt(){ printf "%-30s|%-22s|" "$1" "$(/workspace/executable "DATE_ADD('$1', 0) from /tmp/dfz/f where name='m0.txt'" 2>&1|head -1)"; printf "%-22s\n" "$(/workspace/executable --us-dates "DATE_ADD('$1', 0) from /tmp/dfz/f where name='m0.txt'" 2>&1|head -1)"; }
printf "%-30s|%-22s|%-22s\n" "VALUE" "UK(default)" "--us-dates"
for v in "01/05" "05/01" "12/25" "25/12" "01/05/2017" "05/01/2017" "12/25/2017" "25/12/2017" "1/5" "1/5/17" "2017/05/01" "01-05" "05-01" "01.05.2017" "apr 1" "1 apr" "1 apr 2017" "apr 1 2017" "today" "yesterday" "tomorrow" "-2" "+1" "0" "-0"; do dt "$v"; done
